import{_ as o,o as t,c as a,ak as r}from"./chunks/framework.BQBmvEkd.js";const n="/projects/WonderEcho/en/latest/assets/image1.CNK----C.webp",i="/projects/WonderEcho/en/latest/assets/image4.CZGzzWut.webp",s="/projects/WonderEcho/en/latest/assets/image2.CSKwxi_v.webp",d="/projects/WonderEcho/en/latest/assets/image3.Cg4-GmoH.webp",w=JSON.parse('{"title":"3. Modify Wake-up and Command Words","description":"","frontmatter":{},"headers":[],"relativePath":"docs/3_Modify_Wake_up_and_Command_Words.md","filePath":"docs/3_Modify_Wake_up_and_Command_Words.md"}'),m={name:"docs/3_Modify_Wake_up_and_Command_Words.md"};function c(l,e,h,u,p,f){return t(),a("div",null,[...e[0]||(e[0]=[r('<h1 id="_3-modify-wake-up-and-command-words" tabindex="-1">3. Modify Wake-up and Command Words <a class="header-anchor" href="#_3-modify-wake-up-and-command-words" aria-label="Permalink to &quot;3. Modify Wake-up and Command Words&quot;">​</a></h1><h2 id="_3-1-modify-wake-up-word" tabindex="-1">3.1 Modify Wake-up Word <a class="header-anchor" href="#_3-1-modify-wake-up-word" aria-label="Permalink to &quot;3.1 Modify Wake-up Word&quot;">​</a></h2><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p></p><ul><li>The following features are only available when using the factory firmware provided by our company. (If the factory firmware has been replaced by user-customized firmware, you can find the original factory firmware in the **&quot;<a href="https://drive.google.com/drive/folders/1tD7dg2xF04d26WJP-dF12kazCk4_jtA6?usp=sharing" target="_blank" rel="noreferrer">2. Software Tool &amp; Firmware \\2.Factory Firmware</a>&quot;**folder and re-flash it onto the module. For detailed instructions on how to flash the firmware, please refer to the document <strong>&quot;<a href="https://wiki.hiwonder.com/projects/WonderEcho/en/latest/docs/5_Firmware_Development.html" target="_blank" rel="noreferrer">5. Firmware Development\\5.1.1 Voice Chip Firmware Development</a>&quot;)</strong></li><li>User-customized firmware will not support the following features. If you require these features, please either re-flash the factory firmware or create a new custom firmware that meets your specific needs. The process for creating and flashing firmware is outlined in the document <strong>&quot;<a href="https://wiki.hiwonder.com/projects/WonderEcho/en/latest/docs/5_Firmware_Development.html" target="_blank" rel="noreferrer">5. Firmware Development\\5.1.1 Voice Chip Firmware Development</a>&quot;.</strong></li><li>Please ensure you modify the wake-up word in a quiet environment, as a noisy setting can negatively impact the accuracy of the voice interaction module.</li><li>When speaking the trigger phrase, ensure your voice is clear and loud, and avoid speaking too quickly. It is recommended to stay within a 5-meter distance from the module for optimal performance.</li></ul></div><h3 id="_3-1-1-device-connection" tabindex="-1">3.1.1 Device Connection <a class="header-anchor" href="#_3-1-1-device-connection" aria-label="Permalink to &quot;3.1.1 Device Connection&quot;">​</a></h3><p>Connect the module to the computer with a Type-C cable.</p><img loading="lazy" height="650" width="1024" src="'+n+'" class="common_img"><h3 id="_3-1-2-modify-wake-up-word" tabindex="-1">3.1.2 Modify Wake-up Word <a class="header-anchor" href="#_3-1-2-modify-wake-up-word" aria-label="Permalink to &quot;3.1.2 Modify Wake-up Word&quot;">​</a></h3><img loading="lazy" height="124" width="866" src="'+i+'" class="common_img"><p>(1) Wake up the module by saying <strong>&quot;HELLO-HI-WONDER&quot;</strong>. When the module responds with <strong>&quot;I&#39;m here&quot;</strong>, it indicates that the module is in recognition mode.</p><p>(2) Say the command &quot;<strong>STUDY-WAKE</strong>&quot; to the voice interaction module. If the module responds with &quot;<strong>please say command</strong>,&quot; it means the module has entered wake-up word learning mode.</p><p>(3) Say the desired wake-up word to the module. It is recommended to choose a short word. For example, set <strong>&quot;Hiwonder&quot;</strong> as the wake-up word.</p><p>(4) Once the module successfully recognizes the word, it will announce “<strong>learning succeed,</strong>” confirming that the wake-up word has been successfully modified. You can now use <strong>Hiwonder</strong> to activate the module.</p><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p></p><p>The default wake-up word, <strong>&quot;HELLO-HI-WONDER&quot;</strong>, in the factory firmware is the primary wake-up word and cannot be modified or deleted via voice. The custom wake-up word set by the user can only exist alongside the default wake-up word, meaning only one custom wake-up word can be active in addition to the default.</p></div><h2 id="_3-2-modify-command-word" tabindex="-1">3.2 Modify Command Word <a class="header-anchor" href="#_3-2-modify-command-word" aria-label="Permalink to &quot;3.2 Modify Command Word&quot;">​</a></h2><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p></p><ul><li>The following features are only available when using the factory firmware provided by our company. (If the factory firmware has been replaced by user-customized firmware, you can find the original factory firmware in the <strong>&quot;<a href="https://drive.google.com/drive/folders/1BwrcbH0IMNTDu1GZkbDA22zbrPHjpnIF?usp=sharing" target="_blank" rel="noreferrer">2. Software Tool &amp; Firmware</a>&quot;</strong> folder and re-flash it onto the module. For detailed instructions on how to flash the firmware, please refer to the document &quot;<strong><a href="https://wiki.hiwonder.com/projects/WonderEcho/en/latest/docs/5_Firmware_Development.html" target="_blank" rel="noreferrer">5. Firmware Development\\5.1.1 Voice Chip Firmware Development</a></strong>&quot;)</li><li>User-customized firmware will not support the following features. If you require these features, please either re-flash the factory firmware or create a new custom firmware that meets your specific needs. The process for creating and flashing firmware is outlined in the document &quot;<strong><a href="https://wiki.hiwonder.com/projects/WonderEcho/en/latest/docs/5_Firmware_Development.html" target="_blank" rel="noreferrer">5. Firmware Development\\5.1.1 Voice Chip Firmware Development</a></strong>&quot;.</li><li>Please ensure you modify the wake-up word in a quiet environment, as a noisy setting can negatively impact the accuracy of the voice interaction module.</li><li>When speaking the trigger phrase, ensure your voice is clear and loud, and avoid speaking too quickly. It is recommended to stay within a 5-meter distance from the module for optimal performance.</li></ul></div><h3 id="_3-2-1-device-connection" tabindex="-1">3.2.1 Device Connection <a class="header-anchor" href="#_3-2-1-device-connection" aria-label="Permalink to &quot;3.2.1 Device Connection&quot;">​</a></h3><p>Connect the module to the computer with a Type-C cable.</p><img loading="lazy" height="650" width="1024" src="'+s+'" class="common_img"><h3 id="_3-2-2-modify-command-word" tabindex="-1">3.2.2 Modify Command Word <a class="header-anchor" href="#_3-2-2-modify-command-word" aria-label="Permalink to &quot;3.2.2 Modify Command Word&quot;">​</a></h3><p>The default firmware within the voice recognition module has 4 preset command words that can be modify by voice, as shown below:</p><img loading="lazy" height="340" width="866" src="'+d+'" class="common_img"><p>For example:</p><p>(1) Wake up the module by saying <strong>&quot;HELLO-HI-WONDER&quot;</strong>. When the module responds with <strong>&quot;I&#39;m here&quot;</strong>, it indicates that the module is ready for recognition.</p><p>(2) Say the command &quot;<strong>STUDY-GO-STRAIGHT</strong>&quot; to the module. If it responds with <strong>&quot;Please say command&quot;</strong>, it means the module has entered command word learning mode.</p><p>(3) Say the desired command word to the module. It is recommended to choose a short and clear command. For example, set <strong>&quot;go forward&quot;</strong> as the new command word.</p><p>(4) Once the module successfully recognizes the command, it will broadcast <strong>&quot;learning succeed&quot;</strong>, confirming the modification. From now on, you can use <strong>&quot;go forward&quot;</strong> to perform the same action as the default <strong>&quot;go straight&quot;</strong> command.</p><p>(5) To delete the <strong>go forward</strong> command, simply say <strong>DELETE-GO-STRAIGHT</strong>. Note that only the <strong>go forward</strong> command will be deleted, while <strong>GO-STRAIGHT</strong> will remain unchanged.</p><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p></p><p>The default command words in the firmware cannot be modified or deleted via voice. Any custom command word added can only exist alongside the default ones, meaning only one custom command word can be active at a time in addition to the default commands.</p></div>',28)])])}const y=o(m,[["render",c]]);export{w as __pageData,y as default};
